begin;
insert into public.ce_course2_resources(id,data) values
('course2_module7_pdf','{"base64": "", "sha256": "36ee7a13cae6accc31fc44431590e8afa9baf872a445f2672db14d290af5d20e", "filename": "CE_HALO_Course2_Module07_NPPE_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module7_questions','[{"module_id": "course_2_module_7", "question_id": "course_2_module_7_q01", "question_number": 1, "stem": "Negative pressure pulmonary edema (NPPE) is best described as:", "choice_a": "A hydrostatic noncardiogenic pulmonary edema caused by markedly negative intrathoracic pressure", "choice_b": "A drug-induced pulmonary edema from opioid administration", "choice_c": "A permeability pulmonary edema caused by systemic inflammation", "choice_d": "A cardiogenic pulmonary edema due to left ventricular failure", "correct_choice": "a", "rationale": "NPPE is primarily a hydrostatic noncardiogenic pulmonary edema produced by very negative intrathoracic pressures generated during inspiration against an obstructed upper airway.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q02", "question_number": 2, "stem": "A healthy adult attempting to inhale against a closed glottis can commonly generate intrathoracic pressures in what range?", "choice_a": "-200 to -300 cm H2O", "choice_b": "-50 to -100 cm H2O", "choice_c": "-15 to -25 cm H2O", "choice_d": "-5 to -10 cm H2O", "correct_choice": "b", "rationale": "Approximately -50 to -100 cm H2O is the commonly cited range that can drive NPPE, though susceptibility depends on obstruction severity, duration, and patient factors.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q03", "question_number": 3, "stem": "Which perioperative event is the classic trigger of Type I NPPE?", "choice_a": "Massive transfusion", "choice_b": "Pulmonary embolism during positioning", "choice_c": "Laryngospasm after extubation", "choice_d": "Anaphylaxis to rocuronium", "correct_choice": "c", "rationale": "Type I NPPE most often follows an acute obstruction such as laryngospasm after extubation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q04", "question_number": 4, "stem": "Type II NPPE typically occurs after:", "choice_a": "Rapid infusion of crystalloid", "choice_b": "Prolonged mechanical ventilation with high PEEP", "choice_c": "Neuromuscular blockade with sugammadex reversal", "choice_d": "Sudden relief of a chronic upper airway obstruction (e.g., adult tonsillectomy for OSA)", "correct_choice": "d", "rationale": "Type II NPPE follows sudden relief of chronic upper airway obstruction, when altered airway dynamics and intrathoracic pressures favor edema formation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q05", "question_number": 5, "stem": "Which patient is at the highest classic risk for Type I NPPE based on Holmes et al.''s description?", "choice_a": "Young, muscular, athletic adult (often male) after post-extubation laryngospasm", "choice_b": "Patient with end-stage renal disease on dialysis", "choice_c": "Neonate after routine circumcision", "choice_d": "Frail elderly patient with heart failure", "correct_choice": "a", "rationale": "Young, healthy, athletic adults — often male — can generate large negative intrathoracic pressures and were the group Holmes and colleagues classically described.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q06", "question_number": 6, "stem": "Which finding is most characteristic of NPPE?", "choice_a": "Slow onset dyspnea over several days", "choice_b": "Sudden hypoxemia and frothy or pink sputum after an obstructive event", "choice_c": "Unilateral wheezing without hypoxemia", "choice_d": "Isolated hypercapnia with a clear chest", "correct_choice": "b", "rationale": "Sudden hypoxemia, tachypnea, crackles, and frothy/pink sputum after an obstructive event are hallmark features of NPPE.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q07", "question_number": 7, "stem": "Chest imaging in NPPE typically shows:", "choice_a": "Pneumothorax with tracheal deviation", "choice_b": "Focal consolidation with cavitation", "choice_c": "Diffuse bilateral interstitial and alveolar infiltrates with a normal cardiac silhouette", "choice_d": "Massive pleural effusion", "correct_choice": "c", "rationale": "Diffuse bilateral infiltrates with a normal cardiac silhouette are typical; a normal-sized heart helps distinguish NPPE from cardiogenic edema.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q08", "question_number": 8, "stem": "Which is the most appropriate first intervention when NPPE is suspected in the PACU?", "choice_a": "Administer bronchodilators before assessing the airway", "choice_b": "Administer furosemide 40 mg IV", "choice_c": "Withhold oxygen to avoid oxygen toxicity", "choice_d": "Relieve any residual airway obstruction, apply 100% oxygen, and initiate positive-pressure support", "correct_choice": "d", "rationale": "Treatment is airway-centered: relieve the obstruction, apply 100% oxygen, and provide positive-pressure support before considering pharmacologic adjuncts.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q09", "question_number": 9, "stem": "The commonly cited dose of succinylcholine to break laryngospasm in an adult with IV access is:", "choice_a": "0.1–0.5 mg/kg IV", "choice_b": "1.5–2.5 mg/kg IV", "choice_c": "0.01–0.05 mg/kg IV", "choice_d": "5–10 mg/kg IV", "correct_choice": "a", "rationale": "A subparalytic to low paralytic dose of 0.1–0.5 mg/kg IV is commonly cited to break laryngospasm, with onset in about 30–60 seconds.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q10", "question_number": 10, "stem": "When IV access is not available in a patient with persistent laryngospasm, succinylcholine may be given as:", "choice_a": "20 mg/kg IM", "choice_b": "4 mg/kg IM, maximum 150–200 mg, with onset in approximately 2–3 minutes", "choice_c": "1 mg/kg subcutaneously", "choice_d": "0.1 mg/kg sublingually", "correct_choice": "b", "rationale": "4 mg/kg IM (max 150–200 mg) is the commonly cited IM dose, with onset approximately 2–3 minutes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q11", "question_number": 11, "stem": "Which adverse effect of succinylcholine is most important to consider before repeat dosing in a pediatric patient?", "choice_a": "Chronic constipation", "choice_b": "Peripheral neuropathy", "choice_c": "Vagally mediated bradycardia; consider atropine 0.02 mg/kg IV pretreatment when bradycardia risk is clinically important", "choice_d": "Hepatic failure", "correct_choice": "c", "rationale": "Children are more susceptible to vagally mediated bradycardia during airway manipulation and after succinylcholine, especially with repeat dosing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q12", "question_number": 12, "stem": "The FDA boxed warning for succinylcholine in pediatric patients relates to which catastrophic event?", "choice_a": "Fatal hepatic necrosis", "choice_b": "Delayed-onset renal failure", "choice_c": "Anaphylaxis at first exposure only", "choice_d": "Hyperkalemic rhabdomyolysis and cardiac arrest in children with undiagnosed skeletal muscle myopathy (e.g., Duchenne muscular dystrophy)", "correct_choice": "d", "rationale": "The boxed warning addresses rare but catastrophic hyperkalemic rhabdomyolysis and cardiac arrest in apparently healthy children later found to have undiagnosed myopathy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q13", "question_number": 13, "stem": "A patient with pseudocholinesterase deficiency who receives a standard intubating dose of succinylcholine should be expected to have:", "choice_a": "Prolonged paralysis lasting well beyond the usual duration", "choice_b": "No clinical effect", "choice_c": "Immediate resistance to succinylcholine", "choice_d": "Severe hypertension only", "correct_choice": "a", "rationale": "Pseudocholinesterase deficiency slows the breakdown of succinylcholine, producing prolonged paralysis that requires continued ventilation until spontaneous recovery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q14", "question_number": 14, "stem": "Propofol is used in the laryngospasm–NPPE cascade primarily to:", "choice_a": "Provide long-term sedation in the ICU", "choice_b": "Deepen anesthesia to abort partial laryngospasm and blunt airway reflexes before succinylcholine is required", "choice_c": "Diurese pulmonary edema", "choice_d": "Reverse residual neuromuscular blockade", "correct_choice": "b", "rationale": "Propofol deepens anesthesia and blunts airway reflexes, often aborting partial laryngospasm before succinylcholine is needed.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q15", "question_number": 15, "stem": "A reasonable propofol rescue bolus to deepen anesthesia during laryngospasm in a hemodynamically stable adult is approximately:", "choice_a": "0.05 mg/kg IV", "choice_b": "5.0 mg/kg IV", "choice_c": "0.5–1.0 mg/kg IV", "choice_d": "10 mg/kg IV", "correct_choice": "c", "rationale": "0.5–1.0 mg/kg IV is a commonly used sub-anesthetic to low anesthetic rescue bolus that can abort partial laryngospasm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q16", "question_number": 16, "stem": "Which statement about furosemide in NPPE is most accurate?", "choice_a": "Furosemide replaces the need for positive-pressure ventilation", "choice_b": "Furosemide is contraindicated in NPPE", "choice_c": "Furosemide should be given routinely to every patient with NPPE", "choice_d": "Furosemide is not the primary treatment; use selectively for concomitant volume overload, hypertension, or persistent edema after airway and ventilatory support", "correct_choice": "d", "rationale": "NPPE is driven by hydrostatic fluid shifts, not total-body volume excess. Use furosemide selectively; the definitive treatment is airway relief and positive-pressure support.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q17", "question_number": 17, "stem": "The mainstay of NPPE treatment is:", "choice_a": "Positive airway pressure — CPAP or NIPPV for mild cases, endotracheal intubation with PEEP for severe cases", "choice_b": "High-dose corticosteroids", "choice_c": "Aggressive diuresis", "choice_d": "Bronchoalveolar lavage", "correct_choice": "a", "rationale": "Positive airway pressure is the mainstay: CPAP or NIPPV for mild disease and intubation with PEEP for severe hypoxemia or high work of breathing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q18", "question_number": 18, "stem": "Which is the correct FIRST step in the seven-step laryngospasm treatment algorithm?", "choice_a": "Call the ICU for admission", "choice_b": "Recognize the event early (stridor or silence, paradoxical chest movement, absent capnography, falling SpO2)", "choice_c": "Administer furosemide", "choice_d": "Administer succinylcholine", "correct_choice": "b", "rationale": "Early recognition is step 1. Fast recognition allows immediate corrective steps before large negative intrathoracic pressures develop.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q19", "question_number": 19, "stem": "Which of the following is NOT part of the initial step 3 laryngospasm bundle (100% O2 + CPAP + jaw thrust)?", "choice_a": "Applying continuous positive airway pressure", "choice_b": "Applying 100% oxygen", "choice_c": "Administering IV furosemide", "choice_d": "Performing a vigorous jaw thrust (Larson maneuver)", "correct_choice": "c", "rationale": "Furosemide is not part of the acute laryngospasm response. Step 3 is 100% O2, CPAP, and vigorous jaw thrust, with an oropharyngeal airway if appropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q20", "question_number": 20, "stem": "Most patients with NPPE improve substantially:", "choice_a": "Only after 7 to 10 days of mechanical ventilation", "choice_b": "Only after ECMO", "choice_c": "Within 1 to 2 hours if given furosemide", "choice_d": "Within 12 to 24 hours once the obstruction is relieved and supportive care is provided", "correct_choice": "d", "rationale": "Substantial improvement within 12 to 24 hours after obstruction relief and supportive care is typical; disposition should still be based on sustained clinical improvement.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q21", "question_number": 21, "stem": "Which item is NOT part of the classic differential diagnosis for acute post-extubation hypoxemia consistent with NPPE?", "choice_a": "Chronic pulmonary fibrosis diagnosed years earlier", "choice_b": "Aspiration pneumonitis", "choice_c": "Cardiogenic pulmonary edema", "choice_d": "Anaphylaxis", "correct_choice": "a", "rationale": "Chronic pulmonary fibrosis is a long-standing diagnosis and does not present as new acute post-extubation hypoxemia. The acute differential includes aspiration, cardiogenic edema, anaphylaxis, residual paralysis, bronchospasm, and pulmonary embolism.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q22", "question_number": 22, "stem": "Which extubation strategy is most likely to reduce laryngospasm risk?", "choice_a": "Extubate during Stage 2 anesthesia", "choice_b": "Extubate awake with confirmed neuromuscular reversal (TOF ratio ≥ 0.9 or after sugammadex) and appropriate suctioning", "choice_c": "Extubate without suctioning to minimize stimulation", "choice_d": "Extubate before neuromuscular reversal to save time", "correct_choice": "b", "rationale": "Awake extubation with confirmed reversal and appropriate suctioning reduces the risk of laryngospasm and airway obstruction that precedes NPPE. Stage 2 extubation should be avoided.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q23", "question_number": 23, "stem": "Which patient group deserves heightened peri-extubation vigilance for NPPE?", "choice_a": "Only patients with heart failure", "choice_b": "Only patients under 20 years of age", "choice_c": "Patients with obesity, OSA, upper airway surgery, difficult airway, or young athletic adults", "choice_d": "Only patients with renal disease", "correct_choice": "c", "rationale": "Obesity, OSA, upper airway surgery, known difficult airway, and young muscular adults are recognized higher-risk populations for NPPE.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q24", "question_number": 24, "stem": "Luo, Li, & Qin (2025, BMC Anesthesiology) reported that in selected high-risk populations such as rhinoplasty and spine surgery, the incidence of NPPE can reach:", "choice_a": "0.001%", "choice_b": "0.05%", "choice_c": "Universally 50%", "choice_d": "Approximately 9–11%", "correct_choice": "d", "rationale": "Reported incidence in the general perioperative population is approximately 0.05–0.1%, but selected high-risk populations (rhinoplasty, spine surgery, adult tonsillectomy) can approach 9–11%.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_7", "question_id": "course_2_module_7_q25", "question_number": 25, "stem": "After successful management of NPPE in the PACU, ICU escalation is warranted when the patient:", "choice_a": "Requires reintubation, sustained PEEP, high oxygen requirements, or close hemodynamic and respiratory monitoring", "choice_b": "Has SpO2 98% on room air and is walking", "choice_c": "Refuses to eat breakfast", "choice_d": "Has a normal chest x-ray", "correct_choice": "a", "rationale": "Reintubation, ongoing PEEP, high oxygen requirements, or a need for close hemodynamic and respiratory monitoring are recognized ICU escalation criteria.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module7_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
